import{_ as e,o,c as t,ag as i}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Contratos & OpenAPI 3.1","description":"","frontmatter":{},"headers":[],"relativePath":"pt-br/04-contratos-e-openapi.md","filePath":"pt-br/04-contratos-e-openapi.md"}'),n={name:"pt-br/04-contratos-e-openapi.md"};function s(r,a,d,p,c,l){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="contratos-openapi-3-1" tabindex="-1">Contratos &amp; OpenAPI 3.1 <a class="header-anchor" href="#contratos-openapi-3-1" aria-label="Permalink to &quot;Contratos &amp; OpenAPI 3.1&quot;">​</a></h1><blockquote><p><strong>Sincronização Tipada de Ponta a Ponta</strong><br><em>FastAPI, Pydantic v2, Orval e TanStack Query.</em></p></blockquote><hr><h2 id="_1-fonte-unica-da-verdade" tabindex="-1">1. Fonte Única da Verdade <a class="header-anchor" href="#_1-fonte-unica-da-verdade" aria-label="Permalink to &quot;1. Fonte Única da Verdade&quot;">​</a></h2><p>No SoftForge, o frontend nunca cria tipos manuais ou URLs &quot;chumbadas&quot;. Toda a comunicação é baseada no contrato <strong>OpenAPI 3.1.0</strong> gerado automaticamente a partir dos modelos Pydantic v2 do FastAPI.</p><hr><h2 id="_2-extracao-estatica-a-frio-export-openapi-py" tabindex="-1">2. Extração Estática a Frio (<code>export_openapi.py</code>) <a class="header-anchor" href="#_2-extracao-estatica-a-frio-export-openapi-py" aria-label="Permalink to &quot;2. Extração Estática a Frio (`export_openapi.py`)&quot;">​</a></h2><p>Em frameworks tradicionais, para exportar a especificação OpenAPI você precisa rodar a API, subir banco de dados e bater em <code>http://localhost:8000/openapi.json</code>.</p><p>No SoftForge, o script <code>tools/scripts/export_openapi.py</code> extrai a especificação completa <strong>a frio</strong>, em menos de 1 segundo, instanciando o objeto FastAPI diretamente com banco mockado:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/export_openapi.py</span></span></code></pre></div><p>Isso gera o arquivo canônico <code>apps/api/openapi.json</code>.</p><hr><h2 id="_3-geracao-automatica-de-hooks-no-frontend-orval" tabindex="-1">3. Geração Automática de Hooks no Frontend (<code>Orval</code>) <a class="header-anchor" href="#_3-geracao-automatica-de-hooks-no-frontend-orval" aria-label="Permalink to &quot;3. Geração Automática de Hooks no Frontend (`Orval`)&quot;">​</a></h2><p>O SoftForge integra o <strong>Orval</strong> diretamente ao ciclo de desenvolvimento do frontend.</p><h3 id="execucao-automatica-no-dev-e-build" tabindex="-1">Execução Automática no <code>dev</code> e <code>build</code> <a class="header-anchor" href="#execucao-automatica-no-dev-e-build" aria-label="Permalink to &quot;Execução Automática no `dev` e `build`&quot;">​</a></h3><p>Ao rodar qualquer um dos comandos abaixo em <code>apps/web/</code>, o Orval é disparado antes de iniciar o servidor ou compilar:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Durante o desenvolvimento (roda codegen e inicia o Vite)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Na compilação de produção (roda codegen, checa tipos com tsc e empacota o build)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ou sob demanda:</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codegen</span></span></code></pre></div><p>O Orval gera:</p><ul><li><strong>Modelos TypeScript 100% tipados</strong> em <code>apps/web/src/api/generated/models/</code>.</li><li><strong>Hooks do TanStack Query</strong> (<code>useQuery</code>, <code>useMutation</code>) para cada endpoint da API com gerenciamento automático de cache e estados de loading/error.</li><li><strong>Cliente Axios Pré-configurado</strong> (<code>apps/web/src/lib/api-client.ts</code>) com envio seguro de cookies <code>HttpOnly</code> e interceptors para bearer tokens.</li></ul><hr><h2 id="_4-politica-de-git-qualidade-continua" tabindex="-1">4. Política de Git &amp; Qualidade Contínua <a class="header-anchor" href="#_4-politica-de-git-qualidade-continua" aria-label="Permalink to &quot;4. Política de Git &amp; Qualidade Contínua&quot;">​</a></h2><ul><li><strong>Diretório Ignorado no Git:</strong> A pasta <code>apps/web/src/api/generated/</code> está listada no <code>.gitignore</code> para manter o histórico de commits limpo e livre de artefatos efêmeros gerados por máquina.</li><li><strong>Validação no Pipeline (<code>verify.py</code>):</strong> O script <code>tools/scripts/verify.py</code> executa o typecheck completo do frontend (<code>npm run typecheck</code>), garantindo que qualquer quebra de contrato entre backend e frontend seja detectada imediatamente antes de qualquer entrega ou commit.</li></ul>',22)])])}const m=e(n,[["render",s]]);export{u as __pageData,m as default};
